insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('bmlt-histocyto1-practice-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"The routine fixative used for most histopathology specimens is:","translation":"","options":["10% neutral buffered formalin","Absolute ethanol","Normal saline","Distilled water"],"correctIndex":0,"explanation":"It preserves tissue architecture and limits autolysis and putrefaction.","explanationNe":"१०% neutral buffered formalin ले tissue संरचना जोगाउँछ र autolysis कम गर्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"The usual recommended fixative-to-tissue volume ratio is approximately:","translation":"","options":["10:1","1:10","1:1","2:1"],"correctIndex":0,"explanation":"A generous volume of fixative helps ensure adequate fixation.","explanationNe":"पर्याप्त fixation का लागि tissue भन्दा करिब १० गुणा fixative प्रयोग गरिन्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"The main purpose of fixation is to:","translation":"","options":["Preserve tissue structure","Decalcify every tissue","Stain nuclei","Remove all water instantly"],"correctIndex":0,"explanation":"Fixation stabilises tissue components and prevents decomposition.","explanationNe":"Fixation ले tissue का संरचना स्थिर राखेर बिग्रनबाट जोगाउँछ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"Autolysis refers to:","translation":"","options":["Self-digestion of cells by their enzymes","Bacterial staining","Tissue dehydration","Embedding in wax"],"correctIndex":0,"explanation":"Autolysis occurs when cellular enzymes digest tissue after death or removal.","explanationNe":"कोषका आफ्नै enzyme ले tissue भत्काउनु autolysis हो।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"The routine stain used in histopathology is:","translation":"","options":["Haematoxylin and eosin","Ziehl–Neelsen","Gram stain","Albert stain"],"correctIndex":0,"explanation":"H&E demonstrates nuclei and general tissue architecture.","explanationNe":"H&E stain ले nucleus र tissue को सामान्य बनावट देखाउँछ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"In H&E staining, haematoxylin typically stains nuclei:","translation":"","options":["Blue to purple","Bright green","Orange","Colourless"],"correctIndex":0,"explanation":"Haematoxylin highlights nuclei in blue-purple shades.","explanationNe":"Haematoxylin ले nucleus लाई निलो/बैजनी देखाउँछ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"Eosin typically stains cytoplasm:","translation":"","options":["Pink","Black","Blue","Metallic silver"],"correctIndex":0,"explanation":"Eosin is an acidic dye that stains many cytoplasmic proteins pink.","explanationNe":"Eosin ले cytoplasm का धेरै भाग गुलाबी रंगमा देखाउँछ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"The instrument used to cut thin paraffin sections is a:","translation":"","options":["Microtome","Centrifuge","Autoclave","Colorimeter"],"correctIndex":0,"explanation":"A microtome produces thin sections from paraffin-embedded tissue blocks.","explanationNe":"Microtome ले paraffin block बाट पातलो tissue section काट्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"The usual thickness of routine paraffin sections is approximately:","translation":"","options":["3–5 micrometres","30–50 micrometres","300–500 micrometres","1–2 millimetres"],"correctIndex":0,"explanation":"Routine diagnostic sections are commonly around 3–5 µm thick.","explanationNe":"सामान्य paraffin section प्रायः ३–५ माइक्रोमिटर बाक्लो हुन्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"Paraffin wax embedding mainly provides:","translation":"","options":["Support for cutting thin sections","Bacterial culture medium","A decalcifying solution","A nuclear stain"],"correctIndex":0,"explanation":"Embedding supports tissue and allows reproducible sectioning.","explanationNe":"Paraffin embedding ले tissue लाई support दिएर पातलो काट्न सजिलो बनाउँछ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"Before paraffin infiltration, tissue is dehydrated using:","translation":"","options":["Graded alcohol","Formalin only","Xylene only","Water only"],"correctIndex":0,"explanation":"Increasing alcohol concentrations remove water gradually.","explanationNe":"क्रमशः बढ्दो concentration को alcohol ले tissue बाट पानी हटाउँछ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"The clearing agent commonly used before paraffin infiltration is:","translation":"","options":["Xylene","EDTA","Saline","Glycerol"],"correctIndex":0,"explanation":"Xylene is miscible with alcohol and paraffin and replaces alcohol during clearing.","explanationNe":"Xylene ले alcohol हटाएर paraffin infiltration का लागि tissue तयार गर्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"A tissue cassette is used to:","translation":"","options":["Hold and identify tissue during processing","Measure haemoglobin","Count cells electronically","Culture bacteria"],"correctIndex":0,"explanation":"Cassettes keep tissue organised and identifiable through processing.","explanationNe":"Tissue cassette ले processing भरि नमुना सुरक्षित र पहिचानयोग्य राख्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"Decalcification is required for specimens containing:","translation":"","options":["Calcified tissue such as bone","Normal liver only","Peripheral blood smear","Urine sediment"],"correctIndex":0,"explanation":"Decalcification removes calcium salts so hard tissue can be sectioned.","explanationNe":"हड्डीजस्ता कडा tissue काट्न calcium हटाउने प्रक्रिया decalcification हो।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"A commonly used chelating decalcifying agent is:","translation":"","options":["EDTA","Eosin","Xylene","Paraffin"],"correctIndex":0,"explanation":"EDTA chelates calcium and is relatively gentle, though slower than strong acids.","explanationNe":"EDTA ले calcium बाँधेर हटाउँछ र acid भन्दा तुलनात्मक रूपमा कोमल हुन्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"A frozen section is especially useful for:","translation":"","options":["Rapid intraoperative diagnosis","Long-term tissue storage only","Routine urine analysis","Blood grouping"],"correctIndex":0,"explanation":"Frozen sections can provide a rapid assessment during surgery.","explanationNe":"शल्यक्रियाको समयमा छिटो diagnosis दिन frozen section उपयोगी हुन्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"The instrument used to cut frozen sections is a:","translation":"","options":["Cryostat","Microhematocrit centrifuge","Incubator","Spectrophotometer"],"correctIndex":0,"explanation":"A cryostat is a refrigerated microtome for frozen tissue.","explanationNe":"Cryostat चिसो अवस्थामा tissue काट्ने microtome हो।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"A cytology smear is primarily examined for:","translation":"","options":["Individual cells and cell groups","Whole-organ architecture only","Serum enzymes","Bacterial colony count"],"correctIndex":0,"explanation":"Cytology evaluates cellular morphology rather than full tissue architecture.","explanationNe":"Cytology मा पूरा tissue संरचना होइन, अलग-अलग cell को बनावट हेरिन्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"The conventional cervical screening smear is known as:","translation":"","options":["Pap smear","Widal test","Coombs test","Mantoux test"],"correctIndex":0,"explanation":"The Papanicolaou test examines cervical cells for precancerous and malignant changes.","explanationNe":"Pap smear ले cervix का कोषमा precancerous वा cancerous परिवर्तन खोज्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"The stain classically associated with cervical cytology is:","translation":"","options":["Papanicolaou stain","Ziehl–Neelsen stain","India ink","Albert stain"],"correctIndex":0,"explanation":"Pap stain provides transparent cytoplasm and crisp nuclear detail.","explanationNe":"Pap stain ले cytoplasm र nucleus को विवरण स्पष्ट देखाउँछ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"Fine needle aspiration cytology is abbreviated as:","translation":"","options":["FNAC","FBC","ESR","PT"],"correctIndex":0,"explanation":"FNAC samples cells using a fine needle for cytological assessment.","explanationNe":"FNAC मा मसिनो सुईले cell नमुना लिएर cytology गरिन्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"A major advantage of FNAC is that it is generally:","translation":"","options":["Minimally invasive","Always requires general anaesthesia","A complete substitute for all biopsies","Used only for bone marrow"],"correctIndex":0,"explanation":"FNAC is quick and usually causes limited tissue trauma.","explanationNe":"FNAC छिटो र कम चिरफार हुने परीक्षण हो।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"A biopsy is best described as:","translation":"","options":["Removal of tissue for histopathological examination","Collection of urine for culture","Measurement of blood pressure","Preparation of a blood film"],"correctIndex":0,"explanation":"Biopsy provides tissue architecture for microscopic diagnosis.","explanationNe":"Biopsy मा microscope बाट जाँच्न tissue निकालिन्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"A margin in an excision specimen refers to:","translation":"","options":["The cut edge of the removed tissue","The centre of a nucleus","A staining reagent","The microscope lens"],"correctIndex":0,"explanation":"Margins are assessed to determine whether lesion reaches the resection edge.","explanationNe":"Margin भनेको निकालिएको tissue को काटिएको किनारा हो।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-practice-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"The term dysplasia describes:","translation":"","options":["Abnormal cellular growth and maturation","Normal tissue healing only","Complete absence of cells","Bacterial spore formation"],"correctIndex":0,"explanation":"Dysplasia involves disordered cellular architecture and maturation and may be precancerous.","explanationNe":"Dysplasia मा cell को वृद्धि र maturation असामान्य हुन्छ; यो precancerous हुन सक्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"A small biopsy arrives in an unlabelled container. What is the correct action?","translation":"","options":["Do not process until patient identity is resolved under policy","Guess from the request form","Label it with the ward name only","Discard without documentation"],"correctIndex":0,"explanation":"Correct identification is essential; follow the laboratory discrepancy procedure.","explanationNe":"सही patient identification अनिवार्य छ; policy अनुसार discrepancy समाधान गर्नुपर्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"A tissue specimen is placed in normal saline for several hours instead of fixative. The main concern is:","translation":"","options":["Autolysis and poor preservation","Improved nuclear staining","Immediate paraffin embedding","Decalcification"],"correctIndex":0,"explanation":"Saline is not a routine tissue fixative; delay can damage morphology.","explanationNe":"Saline सामान्य tissue fixative होइन; ढिलाइले tissue morphology बिगार्न सक्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"A large tissue specimen is placed in too little formalin. What is the likely outcome?","translation":"","options":["Inadequate fixation in deeper areas","Perfect fixation throughout","Automatic decalcification","Improved antigen preservation in all cases"],"correctIndex":0,"explanation":"Insufficient fixative volume can leave central tissue poorly fixed.","explanationNe":"Formalin कम हुँदा tissue को भित्री भाग राम्रोसँग fix नहुन सक्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"A tissue section repeatedly detaches from the slide during staining. Which step may help?","translation":"","options":["Use an adhesive-coated slide and ensure proper section adhesion","Skip deparaffinisation","Increase section thickness greatly","Replace H&E with saline"],"correctIndex":0,"explanation":"Adhesive slides and correct drying improve section adherence.","explanationNe":"Adhesive slide र उचित drying ले section slide मा टाँसिन मद्दत गर्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"A paraffin section shows folds and wrinkles. This is most directly a problem during:","translation":"","options":["Section cutting or floating","Patient registration","Tissue fixation only","Microscope calibration only"],"correctIndex":0,"explanation":"Folds can arise from microtomy or improper spreading on the water bath.","explanationNe":"Section काट्दा वा water bath मा फैलाउँदा fold पर्न सक्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-006','BMLT','BMLT NHPC Licensing','mock','free',6,'{"question":"A section is too thick and nuclei overlap. The technician should first review:","translation":"","options":["Microtome section thickness setting","Patient blood group","Formalin colour","Urine specific gravity"],"correctIndex":0,"explanation":"Excessive section thickness can obscure cellular detail.","explanationNe":"Section धेरै बाक्लो हुँदा cell detail छोपिन सक्छ; microtome setting जाँच्नुपर्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"After H&E staining, nuclei appear very pale. Which step should be reviewed?","translation":"","options":["Haematoxylin staining and differentiation/bluing","Eosin concentration only in every case","Tissue cassette number","Water bath temperature only"],"correctIndex":0,"explanation":"Weak nuclear staining may result from inadequate haematoxylin or excessive differentiation.","explanationNe":"Nucleus फिक्का हुँदा haematoxylin staining वा differentiation धेरै भएको छ कि जाँच्नुहोस्।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-008','BMLT','BMLT NHPC Licensing','mock','free',8,'{"question":"A tissue block is difficult to section because it is excessively hard after processing. One possible cause is:","translation":"","options":["Over-dehydration or over-processing","Insufficient patient fasting","Low microscope magnification","Too much mounting medium"],"correctIndex":0,"explanation":"Over-processing can make tissue brittle and difficult to cut.","explanationNe":"धेरै processing/dehydration हुँदा tissue brittle भएर काट्न गाह्रो हुन सक्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-009','BMLT','BMLT NHPC Licensing','mock','free',9,'{"question":"A bone biopsy must be processed for routine sectioning. Which additional step may be necessary?","translation":"","options":["Decalcification","Gram staining","Agglutination","Urine centrifugation"],"correctIndex":0,"explanation":"Calcium salts must be removed sufficiently to allow sectioning.","explanationNe":"Section काट्नुअघि हड्डीको calcium पर्याप्त हटाउन decalcification चाहिन्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-010','BMLT','BMLT NHPC Licensing','mock','free',10,'{"question":"A pathologist requests preservation of enzyme activity in tissue. Which approach is often preferred?","translation":"","options":["Appropriate fresh or frozen tissue handling","Prolonged formalin fixation for every assay","Boiling the specimen","Leaving tissue dry at room temperature"],"correctIndex":0,"explanation":"Some enzyme studies require fresh/frozen tissue because routine fixation can destroy activity.","explanationNe":"केही enzyme परीक्षणका लागि fresh/frozen tissue चाहिन्छ; formalin ले activity नष्ट गर्न सक्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-011','BMLT','BMLT NHPC Licensing','mock','free',11,'{"question":"A cervical smear is heavily obscured by blood and inflammation. The report may be:","translation":"","options":["Unsatisfactory or limited for evaluation","Always positive for cancer","Automatically normal","A bacterial culture result"],"correctIndex":0,"explanation":"Obscuring material can prevent adequate evaluation of cervical cells.","explanationNe":"रगत र inflammation ले cell छोपेमा smear मूल्याङ्कनका लागि अपर्याप्त हुन सक्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-012','BMLT','BMLT NHPC Licensing','mock','free',12,'{"question":"A Pap smear shows koilocytotic change. This is commonly associated with:","translation":"","options":["Human papillomavirus infection","Malaria","Iron deficiency","Hepatitis A"],"correctIndex":0,"explanation":"Koilocytosis is a cytopathic change associated with HPV.","explanationNe":"Koilocytosis HPV संक्रमणसँग सम्बन्धित cell परिवर्तन हो।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-013','BMLT','BMLT NHPC Licensing','mock','free',13,'{"question":"A cytology smear is too thick. What is a likely consequence?","translation":"","options":["Cellular details may be obscured","All cells become viable","Nuclei disappear selectively by fixation","The sample becomes sterile"],"correctIndex":0,"explanation":"Thick smears cause overlapping cells and impair interpretation.","explanationNe":"बाक्लो smear मा cell overlap भएर जाँच्न कठिन हुन्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-014','BMLT','BMLT NHPC Licensing','mock','free',14,'{"question":"An FNAC sample contains very few cells. The report may be:","translation":"","options":["Inadequate or non-diagnostic","Definitively malignant","Definitively benign","A complete histological diagnosis"],"correctIndex":0,"explanation":"Insufficient cellularity limits cytological interpretation.","explanationNe":"Cell कम हुँदा cytology बाट निश्चित निष्कर्ष निकाल्न सकिँदैन।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-015','BMLT','BMLT NHPC Licensing','mock','free',15,'{"question":"A breast lump FNAC shows malignant cells. What does cytology not usually provide as fully as an excision biopsy?","translation":"","options":["Complete tissue architecture and margins","Cell morphology","Nuclear features","Presence of atypical cells"],"correctIndex":0,"explanation":"FNAC assesses cells but does not provide the full architecture or surgical margins.","explanationNe":"FNAC ले cell हेर्छ, तर excision biopsy जस्तो पूरा tissue architecture र margin दिँदैन।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-016','BMLT','BMLT NHPC Licensing','mock','free',16,'{"question":"A specimen for frozen section is sent fresh from theatre. The lab should:","translation":"","options":["Prioritise prompt handling and coordinate with the pathologist","Place it in formalin before every frozen section","Store it at room temperature overnight","Perform routine urine dipstick"],"correctIndex":0,"explanation":"Frozen-section workflow requires rapid communication and correct fresh-tissue handling.","explanationNe":"Frozen section मा छिटो समन्वय र fresh tissue को सही handling चाहिन्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-017','BMLT','BMLT NHPC Licensing','mock','free',17,'{"question":"A histology slide has a detached label. What is the safest approach?","translation":"","options":["Quarantine the slide and resolve identity using traceable records","Guess based on tissue appearance","Write a likely patient name","Issue the report anyway"],"correctIndex":0,"explanation":"Slides must remain traceable to the correct patient and block.","explanationNe":"Slide को पहिचान प्रमाणित अभिलेखबाट मिलाउनुपर्छ; अनुमान गर्नु हुँदैन।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-018','BMLT','BMLT NHPC Licensing','mock','free',18,'{"question":"A specimen is received in formalin, but the request asks for microbiological culture. What should be done?","translation":"","options":["Contact the requesting team because formalin-fixed tissue is unsuitable for routine culture","Culture it directly without review","Neutralise formalin with water and proceed","Report a negative culture"],"correctIndex":0,"explanation":"Formalin kills microorganisms and makes routine culture unsuitable.","explanationNe":"Formalin ले जीवाणु मार्ने भएकाले यस्तो tissue बाट सामान्य culture गर्न मिल्दैन।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-019','BMLT','BMLT NHPC Licensing','mock','free',19,'{"question":"A pathologist asks whether tumour reaches the inked margin. Which part of the specimen is being assessed?","translation":"","options":["Resection edge","Central necrotic area only","Container lid","Adjacent normal blood"],"correctIndex":0,"explanation":"Inked margins mark the cut surfaces and help assess completeness of excision.","explanationNe":"Ink लगाइएको margin ले काटिएको किनारा देखाउँछ र lesion बाँकी छ कि छैन जाँचिन्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-020','BMLT','BMLT NHPC Licensing','mock','free',20,'{"question":"A specimen contains multiple small tissue fragments. The best practice is to:","translation":"","options":["Keep fragments accounted for and process them in a suitable biopsy bag or cassette","Discard the smallest fragments","Mix with another patient''s tissue","Leave fragments on gauze"],"correctIndex":0,"explanation":"Small fragments must be retained and tracked to avoid tissue loss or mix-up.","explanationNe":"सानो fragment हराउन नदिन उपयुक्त biopsy bag/cassette मा राखेर tracking गर्नुपर्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
('bmlt-histocyto1-mock-021','BMLT','BMLT NHPC Licensing','mock','free',21,'{"question":"A tissue processor fails during the dehydration cycle. The technician should:","translation":"","options":["Follow equipment contingency procedure and document the interruption","Open the processor without safety precautions","Ignore the alarm","Release all specimens as fully processed"],"correctIndex":0,"explanation":"A processing interruption can compromise tissue quality and must be managed and documented.","explanationNe":"Processor बिग्रँदा tissue quality असर पर्न सक्छ; सुरक्षित प्रक्रिया अपनाई अभिलेख राख्नुपर्छ।","topic":"Histopathology & Cytology"}'::jsonb,true),
