-- BMLT NHPC Licensing | Histopathology & Cytology Batch 1
-- 25 Practice MCQs + 25 Mock Test questions
-- Safe to re-run: existing content IDs are skipped.
begin;
on conflict (content_id) do nothing;
commit;
select content_type,count(*) as total
from public.learning_content
where faculty='BMLT' and subject='BMLT NHPC Licensing'
and content_data->>'topic'='Histopathology & Cytology'
group by content_type order by content_type;
